`default_nettype none
// Synchronous FIFO, one clock for both sides.
// Implements microarchitecture.md: explicit occupancy counter, pointers that
// wrap at DEPTH-1 (any DEPTH >= 2), first-word fall-through read port.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer AW     = $clog2(DEPTH);
    localparam integer CW     = $clog2(DEPTH + 1);
    localparam integer LAST_I = DEPTH - 1;
    localparam integer ONE_I  = 1;

    localparam [AW-1:0] LAST    = LAST_I[AW-1:0];
    localparam [AW-1:0] PTR_ONE = ONE_I[AW-1:0];
    localparam [CW-1:0] CNT_ONE = ONE_I[CW-1:0];
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];

    reg [AW-1:0]    wr_ptr_q;
    reg [AW-1:0]    wr_ptr_d;
    reg [AW-1:0]    rd_ptr_q;
    reg [AW-1:0]    rd_ptr_d;
    reg [CW-1:0]    count_q;
    reg [CW-1:0]    count_d;
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    wire wr_acc;
    wire rd_acc;

    // Flags are compares on a register: no input-to-flag combinational path.
    assign full    = (count_q == DEPTH_C);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;
    assign rd_data = mem[rd_ptr_q];

    // The flags gate the requests: overflow and underflow policy.
    assign wr_acc = wr_en & ~full;
    assign rd_acc = rd_en & ~empty;

    always @* begin
        wr_ptr_d = wr_ptr_q;
        if (wr_acc) begin
            if (wr_ptr_q == LAST) begin
                wr_ptr_d = {AW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr_q + PTR_ONE;
            end
        end
    end

    always @* begin
        rd_ptr_d = rd_ptr_q;
        if (rd_acc) begin
            if (rd_ptr_q == LAST) begin
                rd_ptr_d = {AW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr_q + PTR_ONE;
            end
        end
    end

    always @* begin
        count_d = count_q;
        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // Control state: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {AW{1'b0}};
            rd_ptr_q <= {AW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage: datapath, not reset, written only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

endmodule
`default_nettype wire
=== END FILE ===
