`default_nettype none
// Self-checking testbench for sync_fifo: two instances (DEPTH 8 x WIDTH 8 and
// DEPTH 5 x WIDTH 12) on the same stimulus, each checked every cycle against
// a reference queue. Coverage goals that are not reached count as failures.
module sync_fifo_tb;

    reg        clk;
    reg        rst_n;
    reg        wr_en;
    reg        rd_en;
    reg [11:0] wr_data;

    wire        full_a;
    wire        empty_a;
    wire [7:0]  rd_data_a;
    wire [3:0]  count_a;
    wire        full_b;
    wire        empty_b;
    wire [11:0] rd_data_b;
    wire [2:0]  count_b;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) dut_a (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data[7:0]), .full(full_a),
        .rd_en(rd_en), .rd_data(rd_data_a), .empty(empty_a),
        .count(count_a)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) dut_b (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full_b),
        .rd_en(rd_en), .rd_data(rd_data_b), .empty(empty_b),
        .count(count_b)
    );

    // Reference queues (circular, far deeper than either FIFO).
    reg [7:0]  qa [0:63];
    reg [11:0] qb [0:63];
    reg [5:0]  qa_head;
    reg [5:0]  qa_tail;
    reg [5:0]  qb_head;
    reg [5:0]  qb_tail;
    reg [3:0]  ca;
    reg [2:0]  cb;
    integer    wp_a;
    integer    rp_a;
    integer    wp_b;
    integer    rp_b;
    reg        wa_a;
    reg        ra_a;
    reg        wa_b;
    reg        ra_b;
    reg        model_valid;

    integer passed;
    integer failed;
    integer i;
    integer ok;
    reg [31:0] rnd;
    reg [2:0]  wr_bias;
    reg [2:0]  rd_bias;
    reg [8*64-1:0] nonce;

    // Coverage counters.
    integer cov_full_a, cov_wrfull_a, cov_drain_a, cov_rdempty_a;
    integer cov_wrrd_empty_a, cov_wrrd_full_a, cov_wrrd_mid_a, cov_wrap_a;
    integer cov_full_b, cov_wrfull_b, cov_drain_b, cov_rdempty_b;
    integer cov_wrrd_empty_b, cov_wrrd_full_b, cov_wrrd_mid_b, cov_wrap_b;
    integer cov_rst_traffic;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Compare every output with the model (state after the last rising edge).
    task check_state;
        begin
            if (model_valid) begin
                if (full_a !== (ca == 4'd8)) begin
                    failed = failed + 1;
                    $error("A: full=%b expected %b at %0t", full_a, (ca == 4'd8), $time);
                end else passed = passed + 1;
                if (empty_a !== (ca == 4'd0)) begin
                    failed = failed + 1;
                    $error("A: empty=%b expected %b at %0t", empty_a, (ca == 4'd0), $time);
                end else passed = passed + 1;
                if (count_a !== ca) begin
                    failed = failed + 1;
                    $error("A: count=%0d expected %0d at %0t", count_a, ca, $time);
                end else passed = passed + 1;
                if (ca != 4'd0) begin
                    if (rd_data_a !== qa[qa_head]) begin
                        failed = failed + 1;
                        $error("A: rd_data=%h expected %h at %0t", rd_data_a, qa[qa_head], $time);
                    end else passed = passed + 1;
                end

                if (full_b !== (cb == 3'd5)) begin
                    failed = failed + 1;
                    $error("B: full=%b expected %b at %0t", full_b, (cb == 3'd5), $time);
                end else passed = passed + 1;
                if (empty_b !== (cb == 3'd0)) begin
                    failed = failed + 1;
                    $error("B: empty=%b expected %b at %0t", empty_b, (cb == 3'd0), $time);
                end else passed = passed + 1;
                if (count_b !== cb) begin
                    failed = failed + 1;
                    $error("B: count=%0d expected %0d at %0t", count_b, cb, $time);
                end else passed = passed + 1;
                if (cb != 3'd0) begin
                    if (rd_data_b !== qb[qb_head]) begin
                        failed = failed + 1;
                        $error("B: rd_data=%h expected %h at %0t", rd_data_b, qb[qb_head], $time);
                    end else passed = passed + 1;
                end
            end
        end
    endtask

    // One clock cycle: called just after a falling edge with inputs set.
    task tick;
        begin
            check_state;

            if (model_valid) begin
                wa_a = wr_en && (ca != 4'd8);
                ra_a = rd_en && (ca != 4'd0);
                wa_b = wr_en && (cb != 3'd5);
                ra_b = rd_en && (cb != 3'd0);
            end else begin
                wa_a = 1'b0;
                ra_a = 1'b0;
                wa_b = 1'b0;
                ra_b = 1'b0;
            end

            if (model_valid && rst_n) begin
                if (ca == 4'd8) cov_full_a = cov_full_a + 1;
                if (wr_en && ca == 4'd8) cov_wrfull_a = cov_wrfull_a + 1;
                if (ra_a && !wa_a && ca == 4'd1) cov_drain_a = cov_drain_a + 1;
                if (rd_en && ca == 4'd0) cov_rdempty_a = cov_rdempty_a + 1;
                if (wr_en && rd_en && ca == 4'd0) cov_wrrd_empty_a = cov_wrrd_empty_a + 1;
                if (wr_en && rd_en && ca == 4'd8) cov_wrrd_full_a = cov_wrrd_full_a + 1;
                if (wr_en && rd_en && ca != 4'd0 && ca != 4'd8) cov_wrrd_mid_a = cov_wrrd_mid_a + 1;
                if ((wa_a && wp_a == 7) || (ra_a && rp_a == 7)) cov_wrap_a = cov_wrap_a + 1;

                if (cb == 3'd5) cov_full_b = cov_full_b + 1;
                if (wr_en && cb == 3'd5) cov_wrfull_b = cov_wrfull_b + 1;
                if (ra_b && !wa_b && cb == 3'd1) cov_drain_b = cov_drain_b + 1;
                if (rd_en && cb == 3'd0) cov_rdempty_b = cov_rdempty_b + 1;
                if (wr_en && rd_en && cb == 3'd0) cov_wrrd_empty_b = cov_wrrd_empty_b + 1;
                if (wr_en && rd_en && cb == 3'd5) cov_wrrd_full_b = cov_wrrd_full_b + 1;
                if (wr_en && rd_en && cb != 3'd0 && cb != 3'd5) cov_wrrd_mid_b = cov_wrrd_mid_b + 1;
                if ((wa_b && wp_b == 4) || (ra_b && rp_b == 4)) cov_wrap_b = cov_wrap_b + 1;
            end
            if (model_valid && !rst_n && (wr_en || rd_en) && ca != 4'd0 && cb != 3'd0)
                cov_rst_traffic = cov_rst_traffic + 1;

            @(posedge clk);

            if (!rst_n) begin
                ca = 4'd0;
                cb = 3'd0;
                qa_head = 6'd0;
                qa_tail = 6'd0;
                qb_head = 6'd0;
                qb_tail = 6'd0;
                wp_a = 0;
                rp_a = 0;
                wp_b = 0;
                rp_b = 0;
                model_valid = 1'b1;
            end else if (model_valid) begin
                if (ra_a) begin
                    qa_head = qa_head + 6'd1;
                    if (rp_a == 7) rp_a = 0; else rp_a = rp_a + 1;
                end
                if (wa_a) begin
                    qa[qa_tail] = wr_data[7:0];
                    qa_tail = qa_tail + 6'd1;
                    if (wp_a == 7) wp_a = 0; else wp_a = wp_a + 1;
                end
                if (wa_a && !ra_a) ca = ca + 4'd1;
                else if (ra_a && !wa_a) ca = ca - 4'd1;

                if (ra_b) begin
                    qb_head = qb_head + 6'd1;
                    if (rp_b == 4) rp_b = 0; else rp_b = rp_b + 1;
                end
                if (wa_b) begin
                    qb[qb_tail] = wr_data;
                    qb_tail = qb_tail + 6'd1;
                    if (wp_b == 4) wp_b = 0; else wp_b = wp_b + 1;
                end
                if (wa_b && !ra_b) cb = cb + 3'd1;
                else if (ra_b && !wa_b) cb = cb - 3'd1;
            end

            @(negedge clk);
        end
    endtask

    task drive;
        input        r;
        input        w;
        input        rd;
        input [11:0] d;
        begin
            rst_n   = r;
            wr_en   = w;
            rd_en   = rd;
            wr_data = d;
            tick;
        end
    endtask

    task cov_chk;
        input integer n;
        input integer id;
        begin
            if (n > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("coverage goal %0d not reached", id);
            end
        end
    endtask

    task random_phase;
        input integer cycles;
        integer k;
        begin
            for (k = 0; k < cycles; k = k + 1) begin
                if ((k % 32) == 0) begin
                    rnd = $random;
                    wr_bias = rnd[2:0];
                    rd_bias = rnd[5:3];
                end
                rnd = $random;
                drive(1'b1, (rnd[2:0] < wr_bias), (rnd[5:3] < rd_bias), rnd[17:6]);
            end
        end
    endtask

    initial begin
        nonce = {(8*64){1'b0}};
        ok = $value$plusargs("nirmaan_nonce=%s", nonce);

        passed = 0;
        failed = 0;
        model_valid = 1'b0;
        ca = 4'd0;
        cb = 3'd0;
        qa_head = 6'd0;
        qa_tail = 6'd0;
        qb_head = 6'd0;
        qb_tail = 6'd0;
        wp_a = 0; rp_a = 0; wp_b = 0; rp_b = 0;
        wa_a = 1'b0; ra_a = 1'b0; wa_b = 1'b0; ra_b = 1'b0;
        wr_bias = 3'd4;
        rd_bias = 3'd4;
        rnd = 32'd0;
        cov_full_a = 0; cov_wrfull_a = 0; cov_drain_a = 0; cov_rdempty_a = 0;
        cov_wrrd_empty_a = 0; cov_wrrd_full_a = 0; cov_wrrd_mid_a = 0; cov_wrap_a = 0;
        cov_full_b = 0; cov_wrfull_b = 0; cov_drain_b = 0; cov_rdempty_b = 0;
        cov_wrrd_empty_b = 0; cov_wrrd_full_b = 0; cov_wrrd_mid_b = 0; cov_wrap_b = 0;
        cov_rst_traffic = 0;

        rst_n   = 1'b0;
        wr_en   = 1'b0;
        rd_en   = 1'b0;
        wr_data = 12'h000;
        @(negedge clk);

        // Reset, with requests that must be ignored.
        drive(1'b0, 1'b1, 1'b1, 12'h5A5);
        drive(1'b0, 1'b1, 1'b1, 12'h3C3);

        // Read while empty.
        drive(1'b1, 1'b0, 1'b1, 12'h000);
        drive(1'b1, 1'b0, 1'b1, 12'h000);

        // Write and read together when empty: only the write is accepted.
        drive(1'b1, 1'b1, 1'b1, 12'h101);

        // Fill to full, then write while full (both depths).
        for (i = 0; i < 10; i = i + 1) begin
            rnd = $random;
            drive(1'b1, 1'b1, 1'b0, rnd[11:0]);
        end

        // Write and read together when full: only the read is accepted.
        drive(1'b1, 1'b1, 1'b1, 12'hABC);

        // Write and read together in between.
        for (i = 0; i < 4; i = i + 1) begin
            rnd = $random;
            drive(1'b1, 1'b1, 1'b1, rnd[11:0]);
        end

        // Drain to empty, then read while empty.
        for (i = 0; i < 12; i = i + 1) begin
            drive(1'b1, 1'b0, 1'b1, 12'h000);
        end

        // Random traffic with random stalls on both sides.
        random_phase(1500);

        // Reset during traffic.
        for (i = 0; i < 6; i = i + 1) begin
            rnd = $random;
            drive(1'b1, 1'b1, 1'b0, rnd[11:0]);
        end
        drive(1'b0, 1'b1, 1'b1, 12'h777);
        drive(1'b1, 1'b0, 1'b0, 12'h000);

        // Full cycle again after reset, then more random traffic.
        for (i = 0; i < 9; i = i + 1) begin
            rnd = $random;
            drive(1'b1, 1'b1, 1'b0, rnd[11:0]);
        end
        for (i = 0; i < 10; i = i + 1) begin
            drive(1'b1, 1'b0, 1'b1, 12'h000);
        end
        random_phase(1500);

        // Final state check.
        drive(1'b1, 1'b0, 1'b0, 12'h000);

        // Coverage goals (ids 1-8 FIFO A, 11-18 FIFO B, 20 reset in traffic).
        cov_chk(cov_full_a, 1);
        cov_chk(cov_wrfull_a, 2);
        cov_chk(cov_drain_a, 3);
        cov_chk(cov_rdempty_a, 4);
        cov_chk(cov_wrrd_empty_a, 5);
        cov_chk(cov_wrrd_full_a, 6);
        cov_chk(cov_wrrd_mid_a, 7);
        cov_chk(cov_wrap_a, 8);
        cov_chk(cov_full_b, 11);
        cov_chk(cov_wrfull_b, 12);
        cov_chk(cov_drain_b, 13);
        cov_chk(cov_rdempty_b, 14);
        cov_chk(cov_wrrd_empty_b, 15);
        cov_chk(cov_wrrd_full_b, 16);
        cov_chk(cov_wrrd_mid_b, 17);
        cov_chk(cov_wrap_b, 18);
        cov_chk(cov_rst_traffic, 20);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
`default_nettype wire
=== END FILE ===
